def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    weeny_patches = image_patch.find("weeny")
    steak_patches = image_patch.find("steak")
    if not weeny_patches or not steak_patches:
        return image_patch
    # Sort weeny patches by depth, from furthest to closest
    weeny_patches.sort(key=lambda w: w.compute_depth(), reverse=True)
    # Find the row of the steak
    steak_row = None
    for steak in steak_patches:
        if steak_row is None or steak.horizontal_center < steak_row.horizontal_center:
            steak_row = steak
    # Find the furthest weeny in the same row as the steak
    for weeny in weeny_patches:
        if weeny.vertical_center == steak_row.vertical_center:
            return weeny
    # If no weeny is in the same row as the steak, return the furthest weeny
    return weeny_patches[0]

